// Writes .env.local with the running local Supabase stack's URL and keys.
//   pnpm db:start && pnpm db:env
// Used locally and in CI before building for e2e. The file is gitignored.
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const out = execSync("pnpm exec supabase status -o json", {
  encoding: "utf8",
  stdio: ["ignore", "pipe", "ignore"],
});
const s = JSON.parse(out.slice(out.indexOf("{")));

const lines = [
  "# Local Supabase stack (pnpm db:start). Generated by `pnpm db:env`; not committed.",
  `NEXT_PUBLIC_SUPABASE_URL=${s.API_URL}`,
  `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${s.PUBLISHABLE_KEY}`,
  `SUPABASE_SECRET_KEY=${s.SECRET_KEY}`,
  `MAILPIT_URL=${s.MAILPIT_URL ?? "http://127.0.0.1:54324"}`,
];
writeFileSync(".env.local", `${lines.join("\n")}\n`);
console.log(`✓ .env.local written for ${s.API_URL}`);
